import { planetHeightAt } from '@shared/world/deposits';
import { hazardsFor } from '@shared/world/hazards';

const SEED = 'HZ-SHARD-SEED';

it('scratch', () => {
  for (const starId of ['star-a', 'star-b', 'star-c', 'star-d', 'star-e']) {
    const gal = generateSystem(SEED, starId);
    for (const planet of gal.planets) {
      if (!planet.landable || planet.class === 'ocean' || planet.class === 'gas') continue;
      const system = { ...gal, systemId: `${gal.systemId}-hz`, planets: [planet] };
      const hazards = hazardsFor(SEED, system);
      const kinds = new Set(hazards.map((h) => h.kind));
      if (kinds.has('storm') && kinds.has('radzone') && kinds.has('drones')) {
        const pads = padsForSystem(SEED, system);
        console.error('SYSTEM', system.systemId, 'PLANET', planet.id);
        for (const h of hazards)
          console.error('HAZARD', h.hazardId, h.kind, JSON.stringify(h.pos), h.radius, h.droneCount,
            'groundAt=', planetHeightAt(SEED, planet, h.pos.x, h.pos.z));
        for (const p of pads)
          console.error('PAD', p.id, JSON.stringify(p.pos),
            'groundAt=', planetHeightAt(SEED, planet, p.pos.x, p.pos.z));
        expect(true).toBe(true);
        return;
      }
    }
  }
  throw new Error('none');
});

