private getTerrain(planetId: string): TerrainContext {
  let ctx = this.terrain.get(planetId);
  if (!ctx) {
    const planet = this.system.planets.find((p) => p.id === planetId);
    if (!planet) throw new Error(`unknown planet id: ${planetId}`);
